entries[8017] = { ["name"] = "Waffe des Felsbeißers", ["text"] = "8% von Grundmana\nSofort\nBenötigt Nahkampfwaffe\nErfüllt die Waffe des Schamanen mit dem Zorn der Erde. Erhöht die gesamte Bedrohungserzeugung um 30% und verringert den erlittenen Schaden um 5%. Hält 30 Min. lang an. [ Elemente entfesseln : Das Entfesseln dieser Verzauberung zwingt das feindliche Ziel, den Schamanen 5 Sek. lang anzugreifen ]" }
entries[8024] = { ["name"] = "Waffe der Flammenzunge", ["text"] = "6% von Grundmana\nSofort\nBenötigt Nahkampfwaffe\nErfüllt die Waffe des Schamanen mit Feuermagie, die den verursachten Zauberschaden um 5% [ Glyphe 'Waffe der Flammenzunge' : und die kritische Zaubertrefferchance um 2% erhöht / erhöht.] Jeder Treffer verursacht zusätzlich 1 bis 1 Feuerschaden, abhängig vom Waffentempo. Langsamere Waffen verursachen pro Schwung mehr Feuerschaden. Hält 30 Minuten lang an. [ Elemente entfesseln : Das Entfesseln dieser Verzauberung fügt einem feindlichen Ziel 1118 Feuerschaden zu und erhöht den verursachten Schaden des nächsten Feuerzaubers des Schamanen um 20 % ]" }
entries[8033] = { ["name"] = "Waffe des Frostbrands", ["text"] = "6% von Grundmana\nSofort\nBenötigt Nahkampfwaffe\nErfüllt die Waffe des Schamanen mit Frostmagie. Bei jedem Treffer besteht eine Chance, zusätzlich 42 Frostschaden zu verursachen und das Bewegungstempo des Ziels 8 Sek. lang um 50 % zu verringern. Hält 30 Minuten lang an. [ Elemente entfesseln : Das Entfesseln dieser Verzauberung fügt einem feindlichen Ziel 873 Frostschaden zu und verringert sein Bewegungstempo 5 Sek. lang um 50 %. Der Effekt wird verstärkt, wenn das Ziel bereits von einem bewegungsverringernden Frosteffekt betroffen ist ]" }
entries[8034] = { ["name"] = "Frostbrandangriff", ["text"] = "100 Meter Reichweite\nSofort\nErfüllt die Waffe des Schamanen mit Frostmagie. Bei jedem Treffer besteht eine Chance, zusätzlich 42 Frostschaden zu verursachen und das Bewegungstempo des Ziels 8 Sek. lang um 50 % zu verringern. Hält 30 Minuten lang an." }
entries[8040] = { ["name"] = "Druidenschlummer", ["text"] = "60 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nVersetzt das feindliche Ziel bis zu 6 Sek. lang in Schlaf. Jegliche feindliche Aktion wird das Ziel wieder aufwecken. Es kann immer nur jeweils ein Ziel in Schlaf versetzt werden." }
entries[8041] = { ["name"] = "Schlangenform", ["text"] = "Sofort\nErmöglicht 10 Sek. lang Gestaltwandlung in eine Schlange, erhöht körperlichen Schaden um 25, Zauber wirken ist allerdings nicht mehr möglich." }
entries[8042] = { ["name"] = "Erdschock", ["text"] = "18% von Grundmana 25 Meter Reichweite\nSofort 6 sek. Abklingzeit\nSchockt das Ziel unmittelbar mit erschütternder Kraft, verursacht 16 Naturschaden und verringert 8 Sek. lang das Nahkampf- und Distanzangriffstempo des Gegners um 20 %." }
