entries[9481] = { ["name"] = "Heilige Pein", ["text"] = "220 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nZerschmettert einen Feind und fügt ihm Heiligschaden zu." }
entries[9482] = { ["name"] = "Flammen verstärken", ["text"] = "30 Meter Reichweite\nWirken in 1 sek.\nErhöht den erlittenen Feuerschaden eines in der Nähe befindlichen Feindes 10 Sek. lang um 100." }
