entries[9484] = { ["name"] = "Untote fesseln", ["text"] = "9% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nFesselt das feindliche untote Ziel bis zu 50 Sek. lang. Die gefesselte Einheit kann sich weder bewegen noch angreifen oder Zauber wirken. Jeglicher zugefügter Schaden wird das Ziel befreien. Es kann immer nur jeweils ein Ziel gefesselt sein." }
