entries[9488] = { ["name"] = "Feuerball", ["text"] = "45 Mana 35 Meter Reichweite\nWirken in 2 sek.\nFügt einem Gegner Feuerschaden zu." }
entries[9489] = { ["name"] = "Wahrsageschale herstellen", ["text"] = "Nahkampfreichweite\nWirken in 2.5 sek.\nTools: Talvashs Wahrsagephiole\nErschafft eine Wahrsageschale, mit der Talvash kontaktiert wird." }
entries[9512] = { ["name"] = "Energie wiederherstellen", ["text"] = "Sofort 1 min Abklingzeit\nStellt sofort [100 - 2 * max(0, 85 - 40)] Energie wieder her." }
